from solution import Entry, Report, solve

assert solve([], 0) == Report(0, 0, 0), 'fixture 0'
assert solve([], 5) == Report(0, 0, 0), 'fixture 1'
assert solve([], 1) == Report(0, 0, 0), 'fixture 2'
assert solve([Entry(3, 8)], 2) == Report(1, 0, 4), 'fixture 3'
assert solve([Entry(1, 6), Entry(3, 7)], 3) == Report(2, 0, 10), 'fixture 4'
assert solve([Entry(2, 11), Entry(0, 0), Entry(0, (-2))], 4) == Report(2, 1, 5), 'fixture 5'
assert solve([Entry(3, 10), Entry(2, 2), Entry(4, 0), Entry(0, 11)], 5) == Report(4, 0, 29), 'fixture 6'
assert solve([Entry(3, 10), Entry(0, 5), Entry(4, 2), Entry(1, 3), Entry(1, 1)], 6) == Report(4, 1, 25), 'fixture 7'
assert solve([Entry(3, 5), Entry(1, (-2)), Entry(3, 11), Entry(4, 2), Entry(0, 10), Entry(3, 6)], 7) == Report(4, 2, 35), 'fixture 8'
assert solve([Entry(1, 5), Entry(1, 1), Entry(3, (-1)), Entry(0, 8), Entry(3, 7), Entry(0, 5), Entry(1, 11)], 8) == Report(3, 4, 22), 'fixture 9'
assert solve([Entry(0, (-3)), Entry(1, 7), Entry(1, 7), Entry(3, (-2)), Entry(4, (-1)), Entry(0, 4), Entry(2, 8), Entry(1, (-2))], 1) == Report(1, 7, 1), 'fixture 10'
assert solve([Entry(2, 10), Entry(2, 11), Entry(4, 2), Entry(3, 1), Entry(2, 1), Entry(2, 4), Entry(0, 2), Entry(3, (-3)), Entry(4, 2)], 2) == Report(2, 7, 13), 'fixture 11'
assert solve([Entry(0, 7), Entry(3, (-3)), Entry(1, 5), Entry(0, 10), Entry(1, 8), Entry(3, 6), Entry(0, 2), Entry(4, 5), Entry(2, (-1)), Entry(0, 1)], 3) == Report(3, 7, 15), 'fixture 12'
assert solve([Entry(2, 5), Entry(4, 3), Entry(3, 11), Entry(1, 8), Entry(3, 4), Entry(0, 1), Entry(4, 3), Entry(1, 5), Entry(4, 6), Entry(1, 9), Entry(4, 7)], 4) == Report(4, 7, 34), 'fixture 13'
assert solve([Entry(1, 3), Entry(1, 7), Entry(3, 4), Entry(2, 6), Entry(2, 11), Entry(1, 0), Entry(0, 2), Entry(1, 10), Entry(1, (-1)), Entry(0, (-1)), Entry(3, 11), Entry(3, (-3))], 5) == Report(4, 8, 27), 'fixture 14'
assert solve([], 6) == Report(0, 0, 0), 'fixture 15'
assert solve([Entry(3, (-1))], 7) == Report(1, 0, 4), 'fixture 16'
assert solve([Entry(0, 4), Entry(4, 8)], 8) == Report(2, 0, 44), 'fixture 17'
assert solve([Entry(3, 7), Entry(0, (-1)), Entry(0, 3)], 1) == Report(1, 2, 4), 'fixture 18'
assert solve([Entry(1, 11), Entry(0, 5), Entry(3, 4), Entry(0, 4)], 2) == Report(2, 2, 4), 'fixture 19'
assert solve([Entry(1, 1), Entry(2, 5), Entry(4, (-3)), Entry(2, 5), Entry(1, (-3))], 3) == Report(3, 2, 23), 'fixture 20'
assert solve([Entry(0, 4), Entry(2, 1), Entry(3, 10), Entry(4, (-3)), Entry(2, 4), Entry(1, 4)], 4) == Report(4, 2, 30), 'fixture 21'
assert solve([Entry(2, 1), Entry(0, 6), Entry(1, 6), Entry(0, 0), Entry(1, 0), Entry(2, 11), Entry(4, (-1))], 5) == Report(4, 3, 31), 'fixture 22'
assert solve([Entry(4, 6), Entry(4, (-1)), Entry(0, (-3)), Entry(2, 9), Entry(0, (-1)), Entry(0, 2), Entry(1, (-2)), Entry(1, (-1))], 6) == Report(4, 4, 43), 'fixture 23'
assert solve([Entry(0, 0), Entry(1, (-1)), Entry(2, 9), Entry(0, 3)], 3) == Report(3, 1, 14), 'fixture 24'
assert solve([Entry(2, 2), Entry(3, 2), Entry(2, 3), Entry(4, 9), Entry(5, 1)], 3) == Report(3, 2, 25), 'fixture 25'
